  for (const e of ev) if (e.at >= cut && e.eps) { const g = n.get(e.fkey) || { e, n: 0 }; g.n += e.eps; n.set(e.fkey, g); }
  return [...n.values()].sort((a, b) => b.n - a.n)[0]?.e || null;
