  return html.trim() ? (n ? `<p class="setcount">${n} ${n === 1 ? "setting" : "settings"}</p>` : "") + html : `<p class="setnone">Nothing for “${esc(S.setQ)}”. Try one word, like “subtitle” or “vpn”.</p>`;
