const KEYS_ALL = [["Search or run a command", ["/"]], ["Home, Library, Journal, Calendar", ["1", "2", "3", "4"]], ["Settings", [","]], ["Move around", ["←", "↑", "↓", "→"]], ["Open", ["↵"]], ["Back", ["Esc"]], ["These keys", ["?"]]];
