const KEYS_HOME = [["Resume", ["↵"]], ["Open the show", ["O"]]];
const KEYS_SHOW = [["Play", ["↵"]], ["Edit your entry", ["E"]], ["Download", ["D"]], ["Mark all watched", ["⇧", "W"]], ["Pick episodes", ["Ctrl", "click"]], ["Pick a run of episodes", ["⇧", "click"]]];
