    const r = f.get(x.e.id) || f.set(x.e.id, { aired: 0, last: null }).get(x.e.id);
    if (x.t <= now && x.ep > r.aired) r.aired = x.ep;
    if (x.ep && x.ep === x.e.episodes) r.last = x.t;
